    "language": "csharp",
    "explanation": "Most applications need to save data permanently (like high scores or configuration settings) to the hard drive. C# provides the `System.IO` namespace for this.\n\nThe `File` class provides static methods to instantly Read, Write, Append, or Check for files on your hard drive.\n\n*Warning: Always remember that File Operations can throw Exceptions (e.g., if the file doesn't exist, or if Windows denies you permission). It is best practice to wrap them in `try/catch` blocks.*",
    "code": "using System;\nusing System.IO; // REQUIRED for File operations\n\nclass Program\n{\n    static void Main()\n    {\n        string filePath = \"C:\\Temp\\log.txt\"; // Use double backslashes in Windows paths\n        \n        // 1. Check if file exists\n        if (!File.Exists(filePath))\n        {\n            // 2. Write completely new text (Overwrites file if it exists)\n            File.WriteAllText(filePath, \"Application Started.\\n\");\n        }\n        \n        // 3. Append text to the end without deleting the old stuff\n        File.AppendAllText(filePath, \"New event logged.\\n\");\n        \n        // 4. Read the entire file into a single string\n        string content = File.ReadAllText(filePath);\n        Console.WriteLine(\"--- FILE CONTENT ---\");\n        Console.WriteLine(content);\n        \n        // 5. Read all lines into an Array (Useful for reading huge lists)\n        string[] allLines = File.ReadAllLines(filePath);\n    }\n}",
